# -*- coding: utf-8 -*-
"""MANAPRINT - Generateur VALIDER HALLOWEEN (A4 portrait, 16 cartons/feuille).

REGLE ABSOLUE : le decor plus bas EST la planche de Maeva, relevee au trait
   sur sa maquette VALIDER HALLOWEEN (le cadre, << N deg ___ >> + << VALIDER >>
   avec sa case cochee, la toile d'araignee et l'araignee, les chauves-souris,
   l'arbre mort, la citrouille, la croix sur sa tombe, les SIX cercles doubles
   labellises N . G . O, et << JOUEZ . COCHEZ . VALIDEZ ! >>). RIEN n'a ete
   redessine : on ECRIT seulement les numeros, centres et gros dans les bulles.

LA REGLE DU JEU : SIX numeros - N 31-45 (2 cercles, haut) . G 46-60 (2 cercles,
   milieu) . O 61-75 (2 cercles, bas). Le crieur sort 31-75.

L'ARC-EN-CIEL EST CARTON PAR CARTON. En N&B au gris #555555.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

